// Hero classes the player can pick (double-click the character). Purely cosmetic for now - each has its own
// pixel portrait (hero_<id> full figure, bust_<id> head-and-shoulders) generated by scripts/pixel.
import type { PixelIconName } from './pixelIcons';

export type PlayerClassId = 'warrior' | 'paladin' | 'ranger' | 'mage';

export interface PlayerClassInfo {
	id: PlayerClassId;
	label: string;
	race: string;
	blurb: string;
	/** Accent for the picker card and its glow */
	accent: string;
	full: PixelIconName;
	bust: PixelIconName;
}

